    const int stride = d + d * ( d - 1 ) / 2;   // number of second derivatives per component
    result.resize( n * stride , numPts );
    for ( int thisPt = 0; thisPt < numPts; thisPt++ ) {
        int r = d;
        for ( int j = 0; j < d; j++ )
        {   
