+template<class T, class KnotVectorType, class Mat>
+index_t gsKnotRemove(
+    KnotVectorType & knots,
+    Mat            & coefs,
+    T                val,
+    index_t              t,
+    bool             update_knots)
+{
+    index_t removed = 0;
+    for (index_t i = 0; i < t; ++i)
+    {
+        if (!gsKnotRemoveSingle<T>(knots, coefs, val, update_knots))
+            break;
+        ++removed;
+    }
+    return removed;
+}
